    @Test
    public void testForID_PositiveOffset() {
        // Testing the branch: return fixedOffsetZone(id, offset);
        String id = "+05:00";
        DateTimeZone result = DateTimeZone.forID(id);
        Assert.assertNotNull(result);
        // The code re-assigns id = printOffset(offset), so we check if it's a fixed zone
        Assert.assertTrue(result.isFixed());
        // 5 hours = 5 * 3600 * 1000 = 18000000 ms
        Assert.assertEquals(18000000, result.getOffset(0));
    }






}

